import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// GET /resource-reservations 는 다른 기능이 만든 API를 화면에서 부르기만 한다.
@Controller('api/v1')
export class FnSfr04006Controller {}

