import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  LookupSelect,
  Pager,
  Pairs,
  RefName,
  Select,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const VIEW_TYPES: [string, string][] = [
  ['일간', '일간'],
  ['주간', '주간'],
  ['월간', '월간'],
];

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

export default function FnSfr04006Page({ role, notify }: PageProps) {
  const [viewType, setViewType] = useState<string>('월간');
  const [baseDate, setBaseDate] = useState<string>(today());
  const [resourceId, setResourceId] = useState<number | string>('');
  const [categoryId, setCategoryId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({ viewType: '월간', baseDate: today(), resourceId: '', resourceCategoryId: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/resource-reservations', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const rows = data?.items ?? [];
  const countOf = (status: string) => rows.filter((r) => r.approvalStatus === status).length;
  const waiting = rows.filter((r) => r.approvalStatus === '신청');

  const search = () => {
    if (!viewType || !baseDate) {
      setFormError('조회 구분과 조회 기준일을 입력하세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setApplied({ viewType, baseDate, resourceId, resourceCategoryId: categoryId });
    reload();
  };

  const reset = () => {
    setViewType('월간');
    setBaseDate(today());
    setResourceId('');
    setCategoryId('');
    setFormError('');
    setPage(0);
    setApplied({ viewType: '월간', baseDate: today(), resourceId: '', resourceCategoryId: '' });
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>예약 현황</h2>
        <Tiles
          items={[
            ['전체 예약', <span>{data?.total ?? 0}건</span>],
            ['신청 (이 쪽)', <span>{countOf('신청')}건</span>],
            ['승인 (이 쪽)', <span>{countOf('승인')}건</span>],
            ['반려 (이 쪽)', <span>{countOf('반려')}건</span>],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>자원예약 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 구분" required>
            <Select value={viewType} onChange={setViewType} options={VIEW_TYPES} />
          </Field>
          <Field label="조회 기준일" required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label="자원">
            <LookupSelect table="resource" role={role} value={resourceId} onChange={setResourceId} placeholder="전체" />
          </Field>
          <Field label="자원 분류">
            <LookupSelect table="resource_category" role={role} value={categoryId} onChange={setCategoryId} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total} />
        <DataTable
          columns={[
            { key: 'title', label: '예약 내용' },
            {
              key: 'resourceId',
              label: '자원',
              render: (r) => <RefName table="resource" role={role} value={r.resourceId} />,
            },
            { key: 'startAt', label: '시작 일시', render: (r) => <DateText value={r.startAt} time /> },
            { key: 'endAt', label: '종료 일시', render: (r) => <DateText value={r.endAt} time /> },
            { key: 'approvalStatus', label: '예약 승인 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
          rows={rows}
          onRowClick={(r) => setSelected(r)}
          empty={loading ? '불러오는 중입니다.' : '조회된 자원예약이 없습니다.'}
        />
        <Pager page={data?.page ?? page} size={data?.size ?? SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>승인 대기</h2>
        <DataTable
          columns={[
            { key: 'title', label: '예약 내용' },
            { key: 'startAt', label: '시작 일시', render: (r) => <DateText value={r.startAt} time /> },
          ]}
          rows={waiting}
          onRowClick={(r) => setSelected(r)}
          empty="승인 대기 예약이 없습니다."
        />
      </section>

      {selected ? (
        <Drawer title="자원예약 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['자원 예약 ID', <span>{String(selected.resourceReservationId ?? '')}</span>],
              ['자원', <RefName table="resource" role={role} value={selected.resourceId} />],
              ['예약 내용', <span>{String(selected.title ?? '')}</span>],
              ['시작 일시', <DateText value={selected.startAt} time />],
              ['종료 일시', <DateText value={selected.endAt} time />],
              ['예약 승인 상태', <Badge value={selected.approvalStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
